{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Absolute oral bioavailability in humans was 43% under fasting conditions at 200 and 400 mg doses, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Absolute oral bioavailability of solifenacin was 88.0% (95% CI 75.8–102.1) in healthy male volunteers after a 10 mg oral dose versus IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Absolute oral bioavailability of lurasidone was 9–19%, below the 20% threshold, arguing against F ≥ 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple absolute human oral bioavailability records (43%, 88%, and additional positive records) consistently support F ≥ 20%; one absolute human record below threshold (9–19%) is outweighed by the preponderance of direct positive evidence.",
  "evidence_gaps": [
    "One direct absolute human record (C11) reports 9–19% bioavailability, below the 20% threshold, creating a mixed signal.",
    "Some positive records were obtained under altered conditions (hepatic cirrhosis, fed state, pediatric, dietary source) or for a metabolite, reducing directness to ordinary parent oral bioavailability.",
    "One record (C33) is qualitative ('high') without a numeric threshold-relevant value, so it is not used as affirmative evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

